(function () {
  var story = new inkjs.Story(JSON.parse(STORY_JSON));
  var out = document.getElementById('out');
  var choicesEl = document.getElementById('choices');
  var scene = document.getElementById('scene');
  var cover = document.getElementById('cover');
  var currentImage = null;
  var SAVE_KEY = 'knotebook:' + document.title;

  if (COVER) {
    cover.src = COVER;
    cover.hidden = false;
  }

  function esc(text) {
    return String(text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function applyTags(tags) {
    if (!tags) return;
    for (var i = 0; i < tags.length; i += 1) {
      var match = /^(?:image|bg):s*(.+)$/i.exec(String(tags[i]).trim());
      if (!match) continue;
      var key = match[1].trim();
      var src = ASSETS[key] || ASSETS['assets/' + key];
      if (src) {
        currentImage = src;
        scene.src = src;
        scene.hidden = false;
      }
      return;
    }
  }

  function paint(text) {
    var blocks = text.split(/\\n{2,}/);
    var html = '';
    for (var i = 0; i < blocks.length; i += 1) {
      var block = blocks[i].replace(/\\n/g, '<br>');
      if (block.trim()) html += '<p>' + block + '</p>';
    }
    out.insertAdjacentHTML('beforeend', html);
    window.scrollTo(0, document.body.scrollHeight);
  }

  function save() {
    try {
      localStorage.setItem(
        SAVE_KEY,
        JSON.stringify({
          state: story.state.ToJson(),
          html: out.innerHTML,
          image: currentImage,
        }),
      );
    } catch (error) {}
  }

  function renderChoices() {
    choicesEl.innerHTML = '';
    var choices = story.currentChoices;
    if (!choices.length) {
      var end = document.createElement('div');
      end.className = 'end';
      end.textContent = 'The End';
      choicesEl.appendChild(end);
      return;
    }
    choices.forEach(function (choice, index) {
      var button = document.createElement('button');
      button.type = 'button';
      button.className = 'choice';
      button.innerHTML =
        '<span class="num">' + (index + 1) + '</span>' + esc(choice.text);
      button.addEventListener('click', function () {
        story.ChooseChoiceIndex(index);
        turn();
      });
      choicesEl.appendChild(button);
    });
  }

  function turn() {
    var text = '';
    while (story.canContinue) {
      text += story.Continue();
      applyTags(story.currentTags);
    }
    if (text.trim()) paint(text.trim());
    renderChoices();
    save();
  }

  function restore() {
    try {
      var raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return false;
      var saved = JSON.parse(raw);
      story.state.LoadJson(saved.state);
      out.innerHTML = saved.html || '';
      if (saved.image) {
        currentImage = saved.image;
        scene.src = saved.image;
        scene.hidden = false;
      }
      renderChoices();
      return true;
    } catch (error) {
      return false;
    }
  }

  document.getElementById('restart').addEventListener('click', function () {
    localStorage.removeItem(SAVE_KEY);
    story = new inkjs.Story(JSON.parse(STORY_JSON));
    out.innerHTML = '';
    choicesEl.innerHTML = '';
    currentImage = null;
    scene.removeAttribute('src');
    scene.hidden = true;
    window.scrollTo(0, 0);
    turn();
  });

  document.addEventListener('keydown', function (event) {
    if (event.key >= '1' && event.key <= '9') {
      var index = Number(event.key) - 1;
      if (story.currentChoices[index]) {
        story.ChooseChoiceIndex(index);
        turn();
      }
    }
  });

  if (!restore()) turn();
})();
